 q('.ev-state').value=mode;q('.ev-loading').hidden=mode!=='loading';q('.ev-error').hidden=mode!=='error';q('.ev-error p').textContent=acquisitionErrors.get(workspace)||'The '+words(workspace)+' reference request failed. Its last valid selection and data are retained.';
