let reservationJob=0,reservationDuration=0;scope.listen(element,'review-disclosure-layout',event=>{if(event.detail.phase==='start'||event.detail.phase==='settled'){reservationDuration=Math.max(reservationDuration,event.detail.duration);if(!reservationJob)reservationJob=requestAnimationFrame(()=>{reservationJob=0;root.layoutReservation.invalidate();reserveDetail(reservationDuration);reservationDuration=0;});}});
q('.ev-workspace').addEventListener('change',e=>select(e.target.value));q('.ev-state').addEventListener('change',e=>setState(e.target.value));q('.ev-load').addEventListener('click',()=>{if(workspace==='capture')loadCapture(captureKind);else{if(workspace==='measured'){measured=domain.projectMeasuredSnapshot(d.measured.snapshot);importedMeasured=false;}setState('populated');}});q('.ev-clear').addEventListener('click',()=>setState('empty'));q('.ev-retry').addEventListener('click',()=>setState('populated'));theme.addEventListener('change',appearance);dark.addEventListener('change',()=>{if(theme.value==='system')appearance();});
async function readSelectedFile(file,kind){
 if(!file)return;const epoch=++fileEpoch;mode='loading';status();try{const content=kind==='measured'?await file.text():await file.arrayBuffer();if(epoch!==fileEpoch||workspace!==kind)return;return kind==='measured'?importMeasuredText(content):importCaptureBuffer(content);}catch(e){if(epoch!==fileEpoch||workspace!==kind)return;mode='error';acquisitionErrors.set(workspace,e.message||String(e));render();q('.ev-error p').textContent=e.message||String(e);return false;}
}
